const fs=require('fs'),path=require('path'),zlib=require('zlib'),cp=require('child_process');
const x=JSON.parse(fs.readFileSync(path.join(process.cwd(),'package.json'),'utf8')).xyacademy,dir=path.resolve('xyacademy-app'),stamp=path.join(dir,'.stamp');
if(!fs.existsSync(stamp)||fs.readFileSync(stamp,'utf8')!==x.id){fs.rmSync(dir,{recursive:true,force:true});const b=zlib.gunzipSync(Buffer.from(x.pack,'base64')),n=b.readUInt32LE(0),ix=JSON.parse(b.subarray(4,4+n).toString('utf8')),base=4+n;for(const [p,[o,l]] of Object.entries(ix)){const t=path.join(dir,p);fs.mkdirSync(path.dirname(t),{recursive:true});fs.writeFileSync(t,b.subarray(base+o,base+o+l));}fs.writeFileSync(path.join(dir,'package.json'),'{"type":"module"}');fs.writeFileSync(stamp,x.id);console.log('XY Academy unpacked ('+Object.keys(ix).length+' files)');}
const c=cp.spawn(process.execPath,[path.join(dir,'server.js')],{stdio:'inherit'});c.on('exit',n=>process.exit(n==null?1:n));for(const s of ['SIGTERM','SIGINT'])process.on(s,()=>c.kill(s));
